WITH with_last AS (SELECT s.*, x.product_brand, x.launch_date FROM suppliers s LEFT JOIN LATERAL (SELECT c.brand AS product_brand, c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.stock_qty DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT product_brand, DATE_TRUNC('WEEK', launch_date) AS week_start, SIZE(COLLECT_SET(product_brand)) AS num_product_brands, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN country = 'SG' THEN 1 END), 0), 2) AS rating_per_sg, ROUND(AVG(rating), 2) AS avg_rating, ROUND(AVG(rating), 2) AS avg_rating_2, ROUND(AVG(rating), 2) AS avg_rating_3 FROM with_last GROUP BY ROLLUP (product_brand, DATE_TRUNC('WEEK', launch_date)) ORDER BY week_start DESC
